    [63040] = {
        id = 63040,
        text = "Dragon Boat Fest Guide: \nThe Dragon Boat Fest is incomplete without Zongzi! Participate in 4 easy steps:\n\n1. Collect Food Ingredient\nYou can collect festival food ingredients in any corner of the game. Check event drops info for details. \n\n2. Make Zongzi\nCollect enough food ingredient to make a Zongzi. There are three types of Zongzi: Cereal Zongzi, Meat Zongzi and Bean Zongzi. \n\n3. Submit Zongzi\nCompleting quests by submitting Zongzi to unlock Dragon Boat Fest exclusive dates and CGs. \n\n4. Exchange Zongzi\nIf you have spare Zongzi, exchange them for rewards like exclusive avatars, avatar frames and badges that are only available in this event.",
        minipack = 0,
    },
