    [2200110] = {
        id = 2200110,
        text = "Brandishes Sandalphon to attack adjacent enemies, making 3 straight strikes. \nStrike 1: Inflicts Physical DMG equal to 60% ATK 1 time; \nStrike 2: Inflicts Physical DMG equal to 70% ATK 1 time; \nStrike 3: Inflicts Physical DMG equal to 70% ATK 1 time.",
