    },
    [1701512] = {
        id = 1701512,
        text = "Surprised. [You Caught Me] (Emotionless).",
        minipack = 0,
    },
    [1701513] = {
        id = 1701513,
        text = "Pleasant. Never thought it would be so interesting.",
        minipack = 0,
    },
    [1701514] = {
        id = 1701514,
        text = "Misjudged. Yuzuru was too hurried.",
        minipack = 0,
    },
    [1701515] = {
        id = 1701515,
        text = "Succeeded. Everything goes as planned.",
        minipack = 0,
    },
    [1701516] = {
        id = 1701516,
        text = "Understood. I will invite you again.",
        minipack = 0,
    },
    [1701517] = {
        id = 1701517,
        text = "Agree. Wonder what kind of clothes will you choose for Yuzuru.",
        minipack = 0,
    },
    [1701518] = {
        id = 1701518,
        text = "Question. Kaguya has this clothesas well?",
        minipack = 0,
    },
    [1701519] = {
        id = 1701519,
        text = "Wonderful. Kaguya will describe it with one of those fancy words.",
        minipack = 0,
    },
    [1701520] = {
        id = 1701520,
        text = "Carious. What do you want to do to Yuzuru at this kind of place?",
        minipack = 0,
    },
    [1701521] = {
        id = 1701521,
        text = "Stand by. Entering the low battery mode.",
        minipack = 0,
    },
    [1701522] = {
        id = 1701522,
        text = "Praise. It is hard to find this kind of delicious food even in the paradise.",
        minipack = 0,
    },
    [1701523] = {
        id = 1701523,
        text = "Acceptable. Since it's from you, I won't hold back.",
        minipack = 0,
    },
    [1701524] = {
        id = 1701524,
        text = "Point out. When girls says [it is so beautiful], you must reply [you are more beautiful].",
        minipack = 0,
    },
    [1701525] = {
        id = 1701525,
        text = "Like it. Thank you, I am happy.",
        minipack = 0,
    },
    [1701526] = {
        id = 1701526,
        text = "Spoil. The bond is strengthened",
        minipack = 0,
    },
    [1701527] = {
        id = 1701527,
        text = "Request. Do you have time for a cold drink?",
        minipack = 0,
    },
    [1701528] = {
        id = 1701528,
        text = "Enhance. Waste resource on useless person? Like Kagu-",
        minipack = 0,
    },
    [1701529] = {
        id = 1701529,
        text = "Question. Why are you staring at Yuzuru?",
        minipack = 0,
    },
    [1701530] = {
        id = 1701530,
        text = "Caution. There is smell of danger in the air.",
