    },
    [1701533] = {
        id = 1701533,
        text = "Competition. Kaguya, Yuzuru will try her best this time.",
        minipack = 0,
    },
    [1701534] = {
        id = 1701534,
        text = "*Sign* Sorry, I have no interest in children.",
        minipack = 0,
    },
    [1701535] = {
        id = 1701535,
        text = "Never thought this would be more fun than fighting.",
        minipack = 0,
    },
    [1701536] = {
        id = 1701536,
        text = "Humph, good performance.",
        minipack = 0,
    },
    [1701537] = {
        id = 1701537,
        text = "So this is what dating feels like? Seems interesting.",
        minipack = 0,
    },
    [1701538] = {
        id = 1701538,
        text = "Boring - boring- don't ask me to do this again.",
        minipack = 0,
    },
    [1701539] = {
        id = 1701539,
        text = "Remember to arrive in time, this is an order.",
        minipack = 0,
    },
    [1701540] = {
        id = 1701540,
        text = "How dare you reject me? (Threating)",
        minipack = 0,
    },
    [1701541] = {
        id = 1701541,
        text = "New combat armor?",
        minipack = 0,
    },
    [1701542] = {
        id = 1701542,
        text = "How troublesome... why must I put on this kind of clothes",
