    },
    [1701543] = {
        id = 1701543,
        text = "As expected, common clothes are not as fun as armor.",
        minipack = 0,
    },
    [1701544] = {
        id = 1701544,
        text = "Are there any new weapons?",
        minipack = 0,
    },
    [1701545] = {
        id = 1701545,
        text = "Show me what you got.",
        minipack = 0,
    },
    [1701546] = {
        id = 1701546,
        text = "Huhh. Well, not bad. Thanks for your efforts. Leave.",
        minipack = 0,
    },
    [1701547] = {
        id = 1701547,
        text = "It is not bad, but maybe some creativity would be nice.",
        minipack = 0,
    },
    [1701548] = {
        id = 1701548,
        text = "Huhh...? It looks different. I can accept it. But don't take it the wrong way.",
        minipack = 0,
    },
    [1701549] = {
        id = 1701549,
        text = "What's this? If you want to please me, do some researches.",
        minipack = 0,
    },
    [1701550] = {
        id = 1701550,
        text = "Well well... Getting praised by someone like you won't make me happy",
        minipack = 0,
    },
    [1701551] = {
        id = 1701551,
        text = "I am the strongest wizard!",
        minipack = 0,
    },
    [1701552] = {
        id = 1701552,
        text = "Just in time to check my new gears.",
        minipack = 0,
    },
    [1701553] = {
        id = 1701553,
        text = "What's up? If it's nothing, could you leave me alone?",
        minipack = 0,
    },
    [1701554] = {
        id = 1701554,
        text = "Just leave it to the most powerful character: me.",
        minipack = 0,
    },
    [1701555] = {
        id = 1701555,
        text = "Because I am the strongest.",
        minipack = 0,
    },
    [1701556] = {
        id = 1701556,
        text = "Yeah! This is me at peak form!",
        minipack = 0,
    },
    [1701557] = {
        id = 1701557,
        text = "Let me see who can stand in my way!",
        minipack = 0,
    },
    [1701558] = {
        id = 1701558,
        text = "Emhehe, where are you taking me?",
